<script>
let price=389,qty=1,flavor='dark';const $=id=>document.getElementById(id);function update(){const total=(price*qty).toFixed(2);$('price').textContent='₱'+total;$('bottom-price').textContent='₱'+total}$('minus').onclick=()=>{qty=Math.max(1,qty-1);$('quantity').textContent=qty;update()};$('plus').onclick=()=>{qty=Math.min(10,qty+1);$('quantity').textContent=qty;update()};document.querySelectorAll('.size-option').forEach(b=>b.onclick=()=>{document.querySelectorAll('.size-option').forEach(x=>x.classList.remove('border-[#855310']));b.classList.add('border-[#855310]');price=Number(b.dataset.price);update()});$('dark-btn').onclick=()=>{flavor='dark';$('product-title').textContent="Juliana's Gourmet Cashews — Dark Chocolate";$('description').textContent='Whole jumbo cashews roasted in small batches, generously enrobed in velvety 60% single-origin dark chocolate. Irresistibly rich, crunchy, and decadent.';$('main-image').src='{{ asset('images/dark-chocolate-cashews.png') }}';price=389;update()};$('classic-btn').onclick=()=>{flavor='classic';$('product-title').textContent="Juliana's Gourmet Cashews — Classic Flavor";$('description').textContent='Plump, premium whole cashews dry-roasted to a crispy golden hue and delicately seasoned with natural sea salt.';$('main-image').src='{{ asset('images/classic-cashews.png') }}';price=349;update()};document.querySelectorAll('.thumb').forEach(b=>b.onclick=()=>{$('main-image').src=b.dataset.image});function toast(message){$('toast').textContent=message;$('toast').classList.remove('opacity-0','-translate-y-5');setTimeout(()=>{$('toast').classList.add('opacity-0','-translate-y-5')},2400)}$('add-cart').onclick=()=>toast(`${qty}x ${flavor==='dark'?'Dark Chocolate':'Classic Roasted'} added to cart!`);$('buy-now').onclick=()=>toast('Proceeding to checkout…');$('quick-classic').onclick=()=>toast('Classic Roasted added to your bag!');
</script>
<script>
async function addCartItem(product, quantity) { const response = await fetch('{{ route('cart.add') }}', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content, 'Accept': 'application/json' }, body: JSON.stringify({ product, quantity }) }); const data = await response.json(); if (response.ok) toast(`${data.message} (${data.count} items)`); }
document.getElementById('add-cart').onclick = () => addCartItem(flavor, qty);
document.getElementById('quick-classic').onclick = () => addCartItem('classic', 1);
</script>
